const savedLang = (()=>{try{return localStorage.getItem('roami-model-prototype-locale')}catch{return null}})()
let locale = savedLang || (navigator.language.toLowerCase().startsWith('en') ? 'en-US' : 'zh-CN')
const t = (key, vars={}) => (pairs[key]?.[locale==='en-US'?1:0] || key).replace(/\{(\w+)\}/g,(_,name)=>String(vars[name]??''))
const e = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))
const icon = name => window.roamiDesignIcons[name] || ''
const n = value => new Intl.NumberFormat(locale,{maximumFractionDigits:2}).format(value)
const money = value => new Intl.NumberFormat(locale,{style:'currency',currency:'USD',maximumFractionDigits:4}).format(value)
const compact = value => new Intl.NumberFormat(locale,{notation:'compact',maximumFractionDigits:1}).format(value)
const localDate = date => new Intl.DateTimeFormat(locale,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(date)
const dateKey = date => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`
const today = dateKey(new Date()), zone = Intl.DateTimeFormat().resolvedOptions().timeZone
