const route=()=>{const [path,query='']=(location.hash.slice(1)||'/catalog').split('?');return{parts:path.split('/').filter(Boolean),query:new URLSearchParams(query)}}
const go=path=>{state.dialog=null;location.hash=path}
const btn=(key,action='',args='',primary=false,extra='')=>`<button type="button" class="btn ${primary?'primary':''}" ${action?`data-action="${action}"`:''} ${args} ${extra}>${t(key)}</button>`
const act=(key,action,args='',ico='')=>`<button type="button" class="tt-act" data-action="${action}" ${args}>${ico?icon(ico):''}${t(key)}</button>`
const ibtn=(key,action,args='',ico='CloseIcon')=>`<button type="button" class="tt-act icon-btn" aria-label="${e(t(key))}" data-action="${action}" ${args}>${icon(ico)}</button>`
const link=(label,path,cls='btn')=>`<a class="${cls}" href="#${e(path)}">${e(label)}</a>`
const field=(key,value,path,type='text',extra='')=>`<label class="field"><span>${t(key)}</span><input aria-label="${e(t(key))}" data-focus="${e(path)}" data-field="${e(path)}" type="${type}" value="${e(value)}" ${extra}></label>`
const select=(key,value,choices,path,extra='')=>`<label class="field"><span>${t(key)}</span><select aria-label="${e(t(key))}" data-focus="${e(path)}" data-field="${e(path)}" ${extra}>${choices.map(([id,label])=>`<option value="${e(id)}" ${String(value)===String(id)?'selected':''}>${e(label)}</option>`).join('')}</select></label>`
const search=(key,path,value)=>`<label class="search">${icon('SearchIcon')}<input aria-label="${e(t(key))}" data-focus="${path}" data-field="${path}" placeholder="${e(t(key))}" value="${e(value||'')}"></label>`
const check=(key,checked,path,args='')=>`<label class="check"><input type="checkbox" data-field="${e(path)}" ${checked?'checked':''} ${args}><span>${t(key)}</span></label>`
const heading=(title,back='',actions='')=>`<header class="tt-pagehead">${back?`<a href="#${e(back)}" class="tt-back" aria-label="${e(t('back'))}">${icon('ChevronLeft')}</a>`:''}<h2>${e(title)}</h2>${back?`<small class="prototype-detail-note">${t('sampleData')}</small>`:''}<div class="page-actions">${actions}</div></header>`
const subtabs=(items,current,base)=>`<nav class="subtabs" aria-label="${e(t('filters'))}">${items.map(([id,key])=>`<a href="#${base}/${id}" ${current===id?'aria-current="page"':''}>${t(key)}</a>`).join('')}</nav>`
const footer=(message,saveAction,args='',label='save',disabled=false)=>`<footer class="form-footer"><span class="muted" role="status">${e(message)}</span><div class="right">${btn('cancel','cancelEdit')}${btn(label,saveAction,args,true,disabled?'disabled':'')}</div></footer>`
const noResults=()=>`<p class="empty">${t('noMatches')}</p>`
const status=(key,cls='')=>`<span class="status ${cls}">${t(key)}</span>`
const badge=key=>`<span class="badge">${t(key)}</span>`
const sourceOptions=()=>[['',t('allSources')],...state.sources.map(s=>[s.id,s.name])]
const modelOptions=(source=state.filters.source)=>[['',t('allModels')],...[...new Set(state.sources.filter(s=>!source||s.id===source).flatMap(s=>s.models.map(m=>m.id)))].map(id=>[id,id])]
const metricLabel=()=>t(state.metric)
function scenarioContent(content,action){if(state.scenario==='loading')return`<div class="scroll" aria-busy="true"><p class="muted">${t('loading')}</p>${'<div class="skeleton"></div>'.repeat(4)}</div>`;if(state.scenario==='empty')return`<div class="scroll"><div class="empty"><p>${t('emptyList')}</p>${action||''}</div></div>`;return`${state.scenario==='failed'?`<div class="notice warn">${t('failure')} ${btn('retry','retry')}</div>`:''}${content}`}
function sourceCards(){const query=(state.queries.sources||'').toLowerCase(),rows=state.sources.filter(s=>(!state.sourceType||s.type===state.sourceType)&&(s.name+' '+s.url).toLowerCase().includes(query));return heading(t('catalog'),'',link(t('addSource'),'/catalog/new/connection','btn primary'))+scenarioContent(`<div class="scroll flow"><div class="toolbar">${search('searchSources','query.sources',state.queries.sources)}${select('kind',state.sourceType,[['',t('all')],['api',t('api')],['plugin',t('plugin')],['local',t('local')]],'sourceType')}</div><div class="cards">${rows.map(s=>`<article class="source-card"><a class="card-open" href="#/catalog/${s.id}/connection" aria-label="${e(s.name)}"></a><div class="card-content"><div class="source-head"><span class="source-mark">${icon(s.type==='plugin'?'ShieldIcon':'LinkIcon')}</span><div><strong>${e(s.name)}</strong><small>${t(s.type)}</small></div>${icon('ChevronRight')}</div><dl class="card-data"><div><span>${t('model')}</span><strong>${s.models.length}</strong></div><div><span>${t('protocol')}</span><strong>${s.protocol}</strong></div></dl><p class="card-models">${s.models.slice(0,3).map(m=>e(m.id)).join(' · ')||t('noModels')}</p><div class="card-bottom"><span>${t('defaultPrice')} · ${t(s.price)}</span>${status('connected','ready')}</div></div></article>`).join('')}</div>${!rows.length?noResults():''}<p class="section-note">${t('demoOnly')}</p></div>`,link(t('addSource'),'/catalog/new/connection','btn primary'))}
function getSourceDraft(id){if(!state.sourceDrafts[id]){const s=id==='new'?{id:'new',name:'',type:'api',url:'',protocol:'OpenAI',models:[],directory:[],price:'unknown',strategy:'smart'}:sourceById(id);state.sourceDrafts[id]=structuredClone(s)}return state.sourceDrafts[id]}
function sourceDetail(id,section='connection'){const s=getSourceDraft(id),original=sourceById(id),isNew=id==='new';const title=isNew?t('addSource'):s.name;const head=heading(title,'/catalog')+(!isNew?subtabs([['connection','connection'],['prices','prices'],['routing','scheduling']],section,`/catalog/${id}`):'');if(section==='prices')return head+sourcePrices(s);if(route().query.has('model'))return head+sourceModelSettings(s,route().query.get('model'));if(section==='routing')return head+`<div class="scroll flow"><div class="form"><h3>${t('sourceRouting')}</h3><p class="section-note">${t('sourceRoutingHint')}</p>${select('policy',s.strategy,strategies.filter(k=>!['weightPolicy','cheap'].includes(k)).map(k=>[k,t(k)]),'source.strategy')}<p class="section-note">${t(s.strategy+'Hint')}</p><details><summary>${icon('ChevronRight')}${t('policyDetails')}</summary><p class="section-note">${t('routeSelection')}</p></details>${btn('save','saveSourceRouting','',true)}</div></div>`;
 if(isNew&&!state.sourceStep||state.editConnection){return head+`<div class="scroll flow"><div class="form">${isNew?`<p class="section-note">${t('connectHint')}</p>${select('kind',s.type,['api','plugin','local'].map(k=>[k,t(k)]),'source.type')}`:''}${field('sourceName',s.name,'source.name')}${s.type==='plugin'?`${select('pluginProvider','WorkBuddy',[['WorkBuddy','WorkBuddy']],'source.pluginProvider')}<p class="section-note">${t('pluginHint')}</p>`:`${field('endpoint',s.url,'source.url','url','placeholder="https://api.example.com/v1"')}${field('credential',s.credential||'', 'source.credential','password',`placeholder="${e(t('keyKept'))}"`)}<details><summary>${icon('ChevronRight')}${t('advanced')}</summary>${select('protocol',s.protocol,[['OpenAI','OpenAI'],['Anthropic','Anthropic']],'source.protocol')}</details>`}${state.validation?`<p role="alert" class="error">${t(state.validation)}</p>`:''}</div></div>${footer(t('demoOnly'),isNew?'connectNext':'saveConnection','',isNew?s.type==='plugin'?'authorize':'connectNext':'save',false)}`}
 if(isNew&&state.sourceStep===1||state.manageSource===id)return head+sourceModelSelection(s,isNew);
 return head+`<div class="scroll flow"><section><div class="summary-row"><span class="source-mark">${icon(s.type==='plugin'?'ShieldIcon':'LinkIcon')}</span><div class="identity"><strong>${e(s.name)}</strong><code class="muted">${e(s.url)}</code></div>${btn('modify','editConnection')}</div><dl class="facts"><div><dt>${t('protocol')}</dt><dd>${s.protocol}</dd></div><div><dt>${t('credential')}</dt><dd>${t('enabled')}</dd></div><div><dt>${t('state')}</dt><dd>${status('connected','ready')}</dd></div></dl>${s.type==='plugin'?`<div class="summary-row"><p class="section-note">${t('pluginHint')}</p>${btn('sameProvider','cloneSource',`data-id="${id}"`)}</div>`:''}</section><section class="divider"><div class="section-head"><h3>${t('configuredCount',{count:s.models.length})}</h3><span class="end">${btn('readModels','manageModels')}</span></div>${s.models.length?`<div class="table-wrap adaptive"><table><thead><tr>${['model','context','capabilities'].map(k=>`<th>${t(k)}</th>`).join('')}<th></th></tr></thead><tbody>${s.models.map(m=>`<tr><td><strong>${e(m.id)}</strong></td><td>${compact(m.ctx)}</td><td>${m.cap.map(badge).join('')||t('notConfirmed')}</td><td>${link(t('prices'),`/catalog/${id}/prices`,'tt-act')}${link(t('modelOptions'),`/catalog/${id}/connection?model=${encodeURIComponent(m.id)}`,'tt-act')}</td></tr>`).join('')}</tbody></table></div><div class="phone-rows">${s.models.map(m=>`<div class="phone-row"><strong>${e(m.id)}</strong><span class="meta">${compact(m.ctx)} · ${m.cap.map(k=>t(k)).join(' · ')}</span><div class="facts">${link(t('prices'),`/catalog/${id}/prices`,'tt-act')}${link(t('modelOptions'),`/catalog/${id}/connection?model=${encodeURIComponent(m.id)}`,'tt-act')}</div></div>`).join('')}</div>`:`<p class="empty">${t('noModels')}</p>`}</section><details class="divider"><summary>${icon('ChevronRight')}${t('more')}</summary>${field('sourceName',s.name,'source.name')}${btn('delete','deleteSource',`data-id="${id}"`,'',state.pools.some(p=>p.members.some(m=>m.source===id))?'disabled':'')}</details></div>`}
function sourceModelSettings(s,id){const m=s.models.find(m=>m.id===id);if(!m)return'';state.nativeDrafts ||= {};const draft=state.nativeDrafts[s.id+'|'+id] ||= {gatewayId:m.gatewayId||m.id};return `<div class="inspector-layout"><div class="scroll flow"><p class="section-note">${t('modelIdentity')}</p></div><aside class="inspector">${heading(t('modelOptions'),'/catalog/'+s.id+'/connection')}<div class="scroll flow"><dl class="key-value"><dt>${t('source')}</dt><dd>${e(s.name)}</dd><dt>${t('upstreamModel')}</dt><dd>${e(id)}</dd></dl>${field('modelAlias',draft.gatewayId,'native.gatewayId')}<p class="section-note">${t('modelIdentity')}</p></div>${footer(t('unsaved'),'saveNative','', 'save',!draft.gatewayId.trim())}</aside></div>`}
function sourceModelSelection(s,isNew){const picked=state.modelSelection||s.models.map(m=>m.id),query=state.queries.directory||'',list=s.directory.filter(m=>m.id.toLowerCase().includes(query.toLowerCase())),added=picked.filter(id=>!s.models.some(m=>m.id===id)).length,removed=s.models.filter(m=>!picked.includes(m.id)).length;return`<div class="scroll flow"><div class="section-head"><h3>${t('selectModels')}</h3><span class="meta">${t('selected',{count:picked.length})}</span><span class="end">${btn('importModels','readDirectory')}</span></div><p class="section-note">${t('upstreamNote')}</p>${search('searchModels','query.directory',query)}<label class="check"><input type="checkbox" data-field="source.selectAll" ${list.length&&list.every(m=>picked.includes(m.id))?'checked':''}><span>${t('selectAll')}</span></label><div class="pool-grid">${list.map(m=>`<label class="model-choice ${picked.includes(m.id)?'is-selected':''}"><input type="checkbox" data-field="source.selectModel" data-model="${e(m.id)}" ${picked.includes(m.id)?'checked':''}><span><strong>${e(m.id)}</strong><small>${compact(m.ctx)} · ${m.cap.map(k=>t(k)).join(' / ')}</small></span></label>`).join('')}</div>${!list.length?noResults():''}<details><summary>${icon('ChevronRight')}${t('addModel')}</summary>${field('manualHint',state.manual||'','source.manual')}${btn('confirm','addManual')}</details></div>${footer(t('changes',{add:added,remove:removed}),isNew?'saveNewSource':'applyModels','',isNew?'saveApply':'applyModels',!picked.length)}`}
function ruleFor(s,id='default'){return state.priceRules[s.id+'|'+id]||{mode:id==='default'?s.price:'inherit',input:s.models.find(m=>m.id===id)?.input??.3,cache:s.models.find(m=>m.id===id)?.cache??.03,output:s.models.find(m=>m.id===id)?.output??1.2,multiplier:1,confirmed:false}}
function priceValues(s,m){const own=ruleFor(s,m?.id||'default'),base=own.mode==='inherit'?ruleFor(s):own;if(base.mode==='free')return[0,0,0];if(base.mode==='tokens'){const multiplier=Number(ruleFor(s).multiplier||1);return[base.input,base.cache,base.output].map(value=>Number(value)*multiplier)}return null}
function validPrice(rule){return rule.mode==='free'?rule.confirmed:rule.mode!=='tokens'||['input','cache','output'].every(key=>String(rule[key]).trim()!==''&&Number.isFinite(Number(rule[key]))&&Number(rule[key])>=0)&&Number(rule.multiplier||1)>0}
function previewPrice(s,id,rule){const base=rule.mode==='inherit'?(id==='default'?{mode:'unknown'}:ruleFor(s)):rule;if(base.mode==='free')return[0,0,0];if(base.mode!=='tokens')return null;const factor=Number(id==='default'?rule.multiplier||1:ruleFor(s).multiplier||1);return[base.input,base.cache,base.output].map(value=>Number(value)*factor)}
function sourcePrices(s){const {query}=route(),editing=query.get('price'),rule=editing?(state.priceDrafts[s.id+'|'+editing] ||= structuredClone(ruleFor(s,editing))):null;const rows=s.models.filter(m=>m.id.toLowerCase().includes((state.queries.prices||'').toLowerCase()));const content=`<div class="scroll flow"><section><div class="section-head"><h3>${t('defaultPrice')}</h3><span class="end">${link(t('editDefault'),`/catalog/${s.id}/prices?price=default`)}</span></div><div class="summary-row"><strong>${t(ruleFor(s).mode)}</strong><span class="meta">${t('unit')}</span></div><p class="section-note">${t('priceChain')}</p></section><section class="divider"><div class="section-head"><h3>${t('model')}</h3><span class="price-unit">${t('unit')}</span></div>${rows.length>8?search('searchModels','query.prices',state.queries.prices):''}<div class="table-wrap adaptive"><table><thead><tr>${['model','priceOrigin','input','cache','output'].map(k=>`<th>${t(k)}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map(m=>{const price=priceValues(s,m),own=ruleFor(s,m.id).mode!=='inherit';return`<tr><td><strong>${e(m.id)}</strong></td><td>${t(own?'modelOverride':'inherited')}</td>${price?price.map(v=>`<td>${n(v)}</td>`).join(''):`<td colspan="3">${t(s.price==='quota'?'quota':'priceUnknown')}</td>`}<td>${link(t('modify'),`/catalog/${s.id}/prices?price=${encodeURIComponent(m.id)}`,'tt-act')}</td></tr>`}).join('')}</tbody></table></div><div class="phone-rows">${rows.map(m=>{const prices=priceValues(s,m);return`<a class="phone-row" href="#/catalog/${s.id}/prices?price=${encodeURIComponent(m.id)}"><div class="section-head"><strong>${e(m.id)}</strong>${icon('ChevronRight')}</div><small>${t(ruleFor(s,m.id).mode!=='inherit'?'modelOverride':'inherited')}</small><div class="facts">${prices?['input','cache','output'].map((key,i)=>`<span>${t(key)} ${n(prices[i])}</span>`).join(''):`<span>${t(s.price==='quota'?'quota':'priceUnknown')}</span>`}</div></a>`}).join('')}</div>${!rows.length?`<div class="empty"><p>${t('noModels')}</p>${link(t('readModels'),`/catalog/${s.id}/connection`)}</div>`:''}</section><p class="section-note">${t('priceNote')}</p></div>`;return`<div class="inspector-layout">${content}${rule?`<aside class="inspector">${heading(t(editing==='default'?'editDefault':'editPrice'),`/catalog/${s.id}/prices`)}<div class="scroll flow"><strong>${e(editing==='default'?s.name:editing)}</strong>${select('priceMethod',rule.mode,[['inherit',t(editing==='default'?'inheritGlobal':'inheritSource')],...['tokens','free','quota','unknown'].map(k=>[k,t(k)])],'price.mode')}${rule.mode==='tokens'?`<p class="price-unit">${t('unit')}</p><div class="inline-fields">${['input','cache','output'].map(key=>field(key,rule[key],'price.'+key,'number','min="0" step="any"')).join('')}</div>`:''}${rule.mode==='free'?`${check('freeConfirm',rule.confirmed,'price.confirmed')}${!rule.confirmed?`<p class="error">${t('freeRequired')}</p>`:''}`:''}${editing==='default'?`<details><summary>${icon('ChevronRight')}${t('priceMultiplier')}</summary>${field('multiplier',rule.multiplier,'price.multiplier','number','min="0.001" max="1000" step="any"')}</details>`:''}<section class="price-preview"><h3>${t('draftPreview')}</h3><div class="price-path"><span>${t(rule.mode==='inherit'?(editing==='default'?'globalDefault':'sourceDefault'):(editing==='default'?'sourceDefault':'modelOverride'))}</span>${icon('ChevronRight')}<strong class="current">${t(rule.mode==='inherit'?s.price:rule.mode)}</strong></div>${previewPrice(s,editing,rule)?`<dl class="facts">${['input','cache','output'].map((key,index)=>`<div><dt>${t(key)}</dt><dd>${validPrice(rule)?n(previewPrice(s,editing,rule)[index]):t('priceUnknown')}</dd></div>`).join('')}</dl><small>${t('unit')}</small>`:`<p class="section-note">${t(rule.mode==='quota'?'quota':'priceUnknown')}</p>`}${rule.mode==='unknown'?`<p class="section-note">${t('noPrice')}</p>`:''}</section>${!validPrice(rule)?`<p role="alert" class="error">${t(rule.mode==='free'?'freeRequired':'priceInvalid')}</p>`:''}</div>${footer(t('unsaved'),'savePrice','', 'save',!validPrice(rule))}</aside>`:''}</div>`}
function poolCards(){return heading(t('aggregate'),'',link(t('addPool'),'/aggregate/new/members','btn primary'))+scenarioContent(`<div class="scroll flow"><div class="cards">${state.pools.map(p=>`<article class="source-card"><a href="#/aggregate/${p.id}/members" class="card-open" aria-label="${e(p.name)}"></a><div class="card-content"><div class="source-head"><span class="source-mark">${icon('LinkIcon')}</span><div><strong>${e(p.name)}</strong><small>${e(p.id)}</small></div>${icon('ChevronRight')}</div><dl class="card-data"><div><span>${t('members')}</span><strong>${p.members.length}</strong></div><div><span>${t('policy')}</span><strong>${t(p.strategy)}</strong></div></dl><p class="card-models">${p.members.slice(0,3).map(m=>e(m.model)).join(' · ')}</p><div class="card-bottom"><span>${t(p.onlyFree?'onlyFree':'allowPaid')}</span>${status('enabled','ready')}</div></div></article>`).join('')}</div><p class="section-note">${t('routeSelection')}</p></div>`,link(t('addPool'),'/aggregate/new/members','btn primary'))}
function poolDraft(id){if(!state.poolDrafts[id])state.poolDrafts[id]=structuredClone(state.pools.find(p=>p.id===id)||{id:'pool-'+Math.random().toString(36).slice(2,9),name:'',onlyFree:true,strategy:'smart',members:[]});return state.poolDrafts[id]}
function poolDetail(id,section='members'){const p=poolDraft(id),s=sourceById(state.pickerSource)||state.sources[0];const head=heading(id==='new'?t('addPool'):p.name,'/aggregate')+subtabs([['members','members'],['routing','routing'],['runtime','runtime']],section,`/aggregate/${id}`);if(section==='members'){const query=(state.queries.pool||'').toLowerCase(),visible=s.models.filter(m=>m.id.toLowerCase().includes(query));return head+`<div class="pool-editor"><div class="pool-basics">${field('poolName',p.name,'pool.name')}${check('onlyFree',p.onlyFree,'pool.onlyFree')}${!p.onlyFree?`<small class="warning">${t('paidWarning')}</small>`:''}</div><section class="pool-selection"><div class="section-head"><h3>${t('poolMembers')}</h3><span class="meta" role="status">${p.members.length} / 64</span></div>${p.members.length?`<div class="pool-chips">${p.members.map((m,i)=>`<div class="pool-chip"><div><strong>${e(m.model)}</strong><small>${e(sourceById(m.source)?.name)}</small></div><button type="button" class="tt-act" aria-label="${e(t('removeMember',{model:m.model,source:sourceById(m.source)?.name}))}" data-action="removeMember" data-index="${i}">${icon('CloseIcon')}</button></div>`).join('')}</div>`:`<p class="section-note">${t('poolEmpty')}</p>`}</section><div class="pool-browser"><nav class="pool-sources" aria-label="${t('source')}">${state.sources.map(row=>`<button type="button" class="source-choice" data-action="pickSource" data-id="${row.id}" aria-pressed="${s.id===row.id}"><span>${e(row.name)}</span><small>${p.members.filter(m=>m.source===row.id).length} / ${row.models.length}</small></button>`).join('')}</nav><section class="pool-models"><div class="section-head"><h3>${e(s.name)}</h3><span class="meta">${t('poolSourceCount',{count:p.members.filter(m=>m.source===s.id).length})}</span></div>${s.models.length>8?search('searchModels','query.pool',state.queries.pool):''}${s.models.length>1?`<label class="check"><input type="checkbox" data-field="pool.all" ${visible.every(m=>p.members.some(c=>c.source===s.id&&c.model===m.id))?'checked':''}><span>${t('selectAll')}</span></label>`:''}<div class="pool-grid">${visible.map(m=>{const selected=p.members.some(c=>c.source===s.id&&c.model===m.id);return`<label class="model-choice ${selected?'is-selected':''}"><input type="checkbox" aria-label="${e(m.id)}" data-field="pool.member" data-model="${e(m.id)}" ${selected?'checked':''} ${!selected&&p.members.length>=64?'disabled':''}><span><strong>${e(m.id)}</strong><small>${compact(m.ctx)} · ${m.cap.map(k=>t(k)).join(' / ')}</small></span></label>`}).join('')}</div>${!visible.length?noResults():''}</section></div>${state.validation?`<p role="alert" class="error">${t(state.validation)}</p>`:''}<details><summary>${icon('ChevronRight')}${t('more')}</summary>${field('poolId',p.id,'pool.id')}<small>${t('autoId')}</small></details></div>${footer(t('selected',{count:p.members.length}),'savePool','', 'saveApply',false)}`}
 if(section==='runtime')return head+`<div class="scroll flow"><p class="section-note">${t('liveHint')}</p>${renderMembers(p,false)}${link(t('monitor'),'/monitor')}</div>`;
 const ranked=previewMembers(p),chosen=ranked[0],weights=ranked.map(()=>0),totalWeight=ranked.reduce((sum,m)=>sum+(m.weight||1),0),rounds=Array.from({length:8},(_,i)=>{if(p.strategy==='rotate')return ranked[i%Math.max(ranked.length,1)];if(p.strategy==='weightPolicy'){ranked.forEach((m,j)=>weights[j]+=m.weight||1);const next=weights.indexOf(Math.max(...weights));weights[next]-=totalWeight;return ranked[next]}return chosen});return head+`<div class="scroll flow"><section class="strategy-top"><div class="form">${select('policy',p.strategy,strategies.map(k=>[k,t(k)]),'pool.strategy')}<p class="section-note">${t(p.strategy+'Hint')}</p><details><summary>${icon('ChevronRight')}${t('policyDetails')}</summary><p class="section-note">${t(p.strategy+'Hint')}</p></details></div><div><div class="section-head"><h3>${t('preview')}</h3><span class="meta">${t('rounds')}</span></div><div class="rounds">${rounds.map(m=>`<span title="${e(m?.model||'')}">${m?p.members.findIndex(row=>keyOf(row)===keyOf(m))+1:0}</span>`).join('')}</div><p class="section-note">${t('nextChoice')} · <strong>${e(chosen?.model||t('poolEmpty'))}</strong></p><details class="failover-test"><summary>${icon('ChevronRight')}${t('failoverTest')}</summary>${check('simulateFailure',state.failedFirst,'failedFirst')}<small>${t('previewHint')}</small></details><small class="preview-note">${t('previewHint')}</small></div></section><section><div class="section-head"><h3>${t('priority')}</h3><span class="meta">${t('memberCount',{count:p.members.length})}</span></div>${renderMembers(p,true)}</section><details class="divider"><summary>${icon('ChevronRight')}${t('requestOptions')}</summary><div class="form">${check('toolRecovery',true,'pool.recovery')}${field('cooldown',p.cooldown||60,'pool.cooldown','number','min="0"')}${field('threshold',p.context||0,'pool.context','number','min="0"')}</div></details></div>${footer(t('unsaved'),'savePool','', 'saveApply')}`}
function previewMembers(p){let rows=[...p.members];if(p.strategy==='fast')rows.sort((a,b)=>a.source==='workbuddy'?-1:b.source==='workbuddy'?1:0);if(p.strategy==='cheap')rows.sort((a,b)=>(sourceById(a.source)?.price==='free'?0:1)-(sourceById(b.source)?.price==='free'?0:1));if(state.failedFirst)rows.push(...rows.splice(0,1));return rows}
function renderMembers(p,editable){return`<ol class="member-list">${p.members.map((m,i)=>`<li class="member-row" data-index="${i}" >${editable?`<button type="button" class="tt-act icon-btn grip" aria-label="${e(t('drag'))}" data-drag="${i}">${icon('DragHandleIcon')}</button>`:''}<span class="badge">${i+1}</span><div class="identity"><strong>${e(m.model)}</strong><small>${e(sourceById(m.source)?.name)}</small></div><div class="member-meta">${status(state.failedFirst&&i===0?'resting':'connected',state.failedFirst&&i===0?'warn':'ready')}<span class="badge">${compact(sourceById(m.source)?.models.find(row=>row.id===m.model)?.ctx||0)}</span>${editable&&p.strategy==='weightPolicy'?`<label class="field">${t('weight')}<input type="number" class="weight-input" aria-label="${e(t('weight'))} ${i+1}" min="1" max="1000" data-field="member.weight" data-index="${i}" value="${m.weight||1}"></label>`:''}</div>${editable?`<div class="row-actions">${act('pin','pinMember',`data-index="${i}"`)}${ibtn('remove','removeMember',`data-index="${i}"`)}</div>`:''}</li>`).join('')}</ol>`}
function filteredCalls(ignorePoint=false){const f=state.filters;return calls.filter(c=>{const day=dateKey(new Date(c.at));return (f.range!=='today'||day===today)&&(f.range!=='custom'||day>=f.start&&day<=f.end)&&(f.range!=='sevenDays'||c.at>Date.now()-7*86400000)&&(ignorePoint||!f.day||day===f.day)&&(!f.source||c.source===f.source)&&(!f.model||c.model===f.model)&&(!f.agent||c.agent===f.agent)&&(!f.status||c.status===f.status)&&(ignorePoint||f.hour===''||String(new Date(c.at).getHours())===f.hour)&&(!f.search||(c.id+' '+c.model).toLowerCase().includes(f.search.toLowerCase()))})}
const metricValue=(rows,metric=state.metric)=>metric==='requestCount'?rows.length:metric==='totalTokens'?rows.reduce((sum,c)=>sum+c.input+c.output,0):metric==='successRate'?100*rows.filter(c=>c.status==='success').length/Math.max(1,rows.length):metric==='firstToken'?(rows.length?Math.max(...rows.map(c=>c.duration*.3)):0):metric==='quality'?(state.checked&&rows.some(c=>c.source===state.checkedSource&&new Date(c.at).getHours()===new Date().getHours())?100:0):rows.reduce((sum,c)=>sum+c.cost,0)
const metricText=(rows,metric=state.metric)=>['successRate','firstToken'].includes(metric)&&!rows.length?t('unchecked'):metric==='cost'?money(metricValue(rows,metric)):metric==='totalTokens'?compact(metricValue(rows,metric)):metric==='firstToken'?n(metricValue(rows,metric))+' ms':metric==='quality'&&!metricValue(rows,metric)?t('unchecked'):['successRate','quality'].includes(metric)?n(metricValue(rows,metric))+'%':n(metricValue(rows,metric))
function filterBar(audit=false){const f=state.filters;return`<div class="toolbar"><div class="segments" aria-label="${t('range')}">${['today','sevenDays','thirtyDays','custom'].map(key=>`<button type="button" data-action="range" data-id="${key}" aria-pressed="${f.range===key}">${t(key)}</button>`).join('')}</div><span class="meta end">${t('timezone',{zone})}</span><span class="mobile-filter-control">${btn('filters','toggleFilters')}</span></div>${f.range==='custom'?`<div class="inline-fields">${field('start',f.start,'filters.start','date')}${field('end',f.end,'filters.end','date')}</div>`:''}<div class="toolbar usage-filter-fields ${state.filtersOpen?'is-open':''}">${select('source',f.source,sourceOptions(),'filters.source')}${select('model',f.model,modelOptions(),'filters.model')}${select('agent',f.agent,[['',t('allAgents')],['Codex','Codex'],['Claude Code','Claude Code'],['Roami','Roami']],'filters.agent')}${audit?select('state',f.status,[['',t('all')],['success',t('success')],['failedCall',t('failedCall')]],'filters.status'):''}</div>${audit?search('searchCalls','filters.search',f.search):''}${filterChips()}`}
function filterChips(){const f=state.filters,entries=[['source',sourceById(f.source)?.name],['model',f.model],['agent',f.agent],['hour',f.hour!==''?f.hour+':00':''],['day',f.day],['status',f.status?t(f.status):'']].filter(([,value])=>value);return entries.length?`<div class="filter-chips">${entries.map(([key,value])=>`<button type="button" class="filter-chip" data-action="clearFilter" data-id="${key}">${e(value)}${icon('CloseIcon')}</button>`).join('')}${act('clear','clearFilters')}</div>`:''}
function totals(rows){return`<section class="metric-strip">${['requestCount','totalTokens','cost'].map(key=>`<div><small>${t(key)}</small><strong>${metricText(rows,key)}</strong></div>`).join('')}</section>`}
function groupRows(rows){const group=state.group,keys=group==='byTotal'?[t('byTotal')]:[...new Set(rows.map(c=>group==='bySource'?c.source:group==='byAgent'?c.agent:c.model))];return keys.map(key=>({key,name:group==='bySource'?sourceById(key)?.name||key:key,calls:group==='byTotal'?rows:rows.filter(c=>(group==='bySource'?c.source:group==='byAgent'?c.agent:c.model)===key)})).sort((a,b)=>metricValue(b.calls)-metricValue(a.calls))}
function chart(rows,metric=state.metric,forMonitor=false){const points=state.grain==='day'&&!forMonitor?Array.from({length:state.filters.range==='thirtyDays'?30:7},(_,i)=>{const date=new Date();date.setDate(date.getDate()-(state.filters.range==='thirtyDays'?29:6)+i);const key=dateKey(date);return{key,label:state.filters.range==='thirtyDays'&&i%5!==0?'':new Intl.DateTimeFormat(locale,{month:'numeric',day:'numeric'}).format(date),rows:rows.filter(c=>dateKey(new Date(c.at))===key)}}):Array.from({length:24},(_,i)=>({key:String(i),label:i%3===0?String(i).padStart(2,'0'):'',rows:rows.filter(c=>new Date(c.at).getHours()===i)}));const peak=Math.max(1,...points.map(p=>metricValue(p.rows,metric)));return`<div class="chart-area" role="group" aria-label="${t('trend')}">${points.map(p=>`<button type="button" class="chart-point" data-action="${forMonitor?'monitorPoint':'point'}" data-id="${p.key}" aria-pressed="${state.filters.hour===p.key}" aria-label="${e(p.key)} · ${e(metricText(p.rows,metric))}" title="${e(p.key)} · ${e(metricText(p.rows,metric))}">${p.rows.length&&(metric!=='quality'||metricValue(p.rows,metric)>0)?`<i style="height:${Math.max(3,metricValue(p.rows,metric)/peak*88)}%"></i>`:''}<small>${p.label||'&nbsp;'}</small></button>`).join('')}</div>`}
function overview(){const rows=filteredCalls(),chartRows=filteredCalls(true),groups=groupRows(rows),quotaRows=calls.filter(c=>dateKey(new Date(c.at))===today);return heading(t('usage'))+scenarioContent(`<div class="scroll flow">${filterBar()}${totals(rows)}<div class="quota-line"><span>${t('quotaSummary',{cost:money(metricValue(quotaRows,'cost')),limit:state.dailyLimit?money(state.dailyLimit):t('unlimited')})}</span>${act('limit','editLimit')}</div><section><div class="chart-head"><h3>${t('trend')}</h3><div class="segments">${['requestCount','totalTokens','cost'].map(key=>`<button type="button" data-action="metric" data-id="${key}" aria-pressed="${state.metric===key}">${t(key)}</button>`).join('')}</div><div class="end">${select('grain',state.grain,[['hour',t('hour')],['day',t('day')]],'grain')}</div></div>${chartRows.length?chart(chartRows):`<p class="empty">${t('noCalls')}</p>`}<div class="summary-row"><div class="interval-choice">${state.grain==='hour'?select('interval',state.filters.hour,[['',t('entirePeriod')],...Array.from({length:24},(_,hour)=>[String(hour),String(hour).padStart(2,'0')+':00'])],'filters.hour'):''}</div><p class="section-note">${state.filters.hour!==''?t('focusedHour',{hour:state.filters.hour}):state.filters.day?t('focusedDay',{day:state.filters.day}):t('periodSummary')} · ${metricText(rows,'requestCount')} ${t('requestCount')}</p><span class="end">${btn('drill','drill','',true)}</span></div></section><section class="divider"><div class="section-head"><h3>${t('breakdown')}</h3><span class="end">${select('groupBy',state.group,['byModel','bySource','byAgent','byTotal'].map(k=>[k,t(k)]),'group')}</span></div><div class="table-wrap adaptive"><table><thead><tr><th>${t(state.group)}</th><th>${t('requestCount')}</th><th>${t('totalTokens')}</th><th>${t('cost')}</th><th></th></tr></thead><tbody>${groups.map(group=>`<tr><td><strong>${e(group.name)}</strong><span class="comparison-meter"><i style="width:${group.calls.length/Math.max(1,rows.length)*100}%"></i></span></td><td>${group.calls.length}</td><td>${metricText(group.calls,'totalTokens')}</td><td>${metricText(group.calls,'cost')}</td><td>${act('inspect','drillGroup',`data-id="${e(group.key)}"`)}</td></tr>`).join('')}</tbody></table></div><div class="phone-rows">${groups.map(group=>`<button type="button" class="phone-row" data-action="drillGroup" data-id="${e(group.key)}"><div class="section-head"><strong>${e(group.name)}</strong>${icon('ChevronRight')}</div><div class="facts"><span>${group.calls.length} ${t('requestCount')}</span><span>${metricText(group.calls,'totalTokens')} Token</span><span>${metricText(group.calls,'cost')}</span></div></button>`).join('')}</div></section><p class="section-note">${t('priceNote')}</p></div>`,link(t('catalog'),'/catalog'))}
function auditPage(id){const all=filteredCalls(),pages=Math.max(1,Math.ceil(all.length/20)),page=Math.min(state.usagePage,pages),rows=all.slice((page-1)*20,page*20),selected=calls.find(c=>c.id===id);return heading(t('audit'))+`<div class="inspector-layout">${scenarioContent(`<div class="scroll flow">${state.fromOverview?`<p class="section-note">${t('auditFrom')}</p>`:''}${filterBar(true)}<div class="section-head"><h3>${t('requestCount')} · ${n(all.length)}</h3><span class="meta">${t('timezone',{zone})}</span></div><div class="table-wrap adaptive"><table><thead><tr>${['timestamp','source','model','agent','totalTokens','cost','state'].map(k=>`<th>${t(k)}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map(c=>`<tr><td>${localDate(c.at)}</td><td>${e(sourceById(c.source)?.name)}</td><td><strong>${e(c.model)}</strong><small>${c.id}</small></td><td>${c.agent}</td><td>${compact(c.input+c.output)}</td><td>${money(c.cost)}</td><td>${status(c.status,c.status==='success'?'ready':'warn')}</td><td>${link(t('inspect'),'/audit/'+c.id,'tt-act')}</td></tr>`).join('')}</tbody></table></div><div class="phone-rows">${rows.map(c=>`<a class="phone-row" href="#/audit/${c.id}"><div class="section-head"><strong>${e(c.model)}</strong>${icon('ChevronRight')}</div><small>${e(sourceById(c.source)?.name)} · ${c.agent}</small><div class="facts"><span>${localDate(c.at)}</span><span>${t(c.status)}</span><span>${compact(c.input+c.output)} Token</span></div></a>`).join('')}</div>${!rows.length?`<p class="empty">${t('noCalls')}</p>`:''}${pages>1?`<nav class="pager" aria-label="${t('page',{page,total:pages})}">${btn('previous','page',`data-id="${page-1}"`,false,page<=1?'disabled':'')}<span>${t('page',{page,total:pages})}</span>${btn('next','page',`data-id="${page+1}"`,false,page>=pages?'disabled':'')}</nav>`:''}</div>`,link(t('catalog'),'/catalog'))}${selected?`<aside class="inspector">${heading(t('requestDetails'),'/audit')}<div class="scroll flow"><div><h3>${e(selected.model)}</h3><small>${selected.id}</small></div>${status(selected.status,selected.status==='success'?'ready':'warn')}<dl class="key-value">${[['timestamp',localDate(selected.at)],['source',sourceById(selected.source)?.name],['agent',selected.agent],['duration',n(selected.duration/1000)+' s'],['statusCode',selected.status==='success'?'200':'429']].map(([key,value])=>`<dt>${t(key)}</dt><dd>${e(value)}</dd>`).join('')}</dl><section class="divider flow"><h3>${t('usageReceipt')}</h3><dl class="key-value">${['input','cache','output'].map(key=>`<dt>${t(key)}</dt><dd>${n(selected[key])}</dd>`).join('')}</dl></section><section class="divider flow"><h3>${t('priceSnapshot')}</h3><p>${money(selected.cost)}</p><small>${t('priceNote')}</small></section>${selected.status==='failedCall'?`<details class="divider" open><summary>${icon('ChevronRight')}${t('failDetails')}</summary><p class="section-note">${t('rateLimited')}</p><code>MODEL_RATE_LIMITED</code></details>`:''}</div></aside>`:''}</div>`}
function monitorPage(id){const rows=calls.filter(c=>c.at>Date.now()-Number(state.monitorHours)*3600000&&(!state.monitorSource||c.source===state.monitorSource)&&(!state.monitorModel||c.model===state.monitorModel)),sources=state.sources.filter(s=>!state.monitorSource||s.id===state.monitorSource),selected=sourceById(id),head=heading(t('monitor'));return head+`<div class="inspector-layout">${scenarioContent(`<div class="scroll flow"><div class="mobile-filter-control section-head"><span class="meta">${t(state.monitorHours==='1'?'oneHour':state.monitorHours==='6'?'sixHours':'recent24')}</span><span class="end">${btn('filters','toggleMonitorFilters')}</span></div><div class="toolbar monitor-filter-fields ${state.monitorFiltersOpen?'is-open':''}">${select('source',state.monitorSource||'',sourceOptions(),'monitorSource')}${select('model',state.monitorModel||'',modelOptions(state.monitorSource||''),'monitorModel')}${select('monitorRange',state.monitorHours,[['1',t('oneHour')],['6',t('sixHours')],['24',t('recent24')]],'monitorHours')}</div><p class="section-note">${t('retention')}</p><section class="metric-strip"><div><small>${t('successRate')}</small><strong>${new Intl.NumberFormat(locale,{style:'percent',maximumFractionDigits:1}).format(rows.filter(c=>c.status==='success').length/Math.max(1,rows.length))}</strong></div><div><small>${t('firstToken')}</small><strong>${rows.length?'740 ms':t('unchecked')}</strong></div><div><small>${t('quality')}</small><strong>${state.checked&&(!state.monitorSource||state.monitorSource===state.checkedSource)?'100%':t('unchecked')}</strong></div></section><section><div class="section-head"><h3>${t('trend')}</h3><span class="end">${select('metric',state.monitorMetric,['successRate','firstToken','quality'].map(k=>[k,t(k)]),'monitorMetric')}</span></div>${state.monitorMetric==='quality'&&!state.checked?`<div class="empty"><p>${t('notGraded')}</p>${btn('checkModel','openCheck')}</div>`:chart(rows,state.monitorMetric,true)}</section><section class="divider"><div class="section-head"><h3>${t('sourceComparison')}</h3></div><div class="table-wrap adaptive"><table><thead><tr>${['source','requestCount','successRate','firstToken','quality'].map(k=>`<th>${t(k)}</th>`).join('')}<th></th></tr></thead><tbody>${sources.map((s,i)=>{const list=rows.filter(c=>c.source===s.id);return`<tr><td><strong>${e(s.name)}</strong></td><td>${list.length}</td><td>${list.length?new Intl.NumberFormat(locale,{style:'percent',maximumFractionDigits:1}).format(list.filter(c=>c.status==='success').length/list.length):t('unchecked')}</td><td>${list.length?n(540+i*110)+' ms':t('unchecked')}</td><td>${state.checkedSource===s.id?'100%':t('notGraded')}</td><td>${link(t('inspect'),'/monitor/'+s.id,'tt-act')}</td></tr>`}).join('')}</tbody></table></div><div class="phone-rows">${sources.map((s,i)=>`<a class="phone-row" href="#/monitor/${s.id}"><div class="section-head"><strong>${e(s.name)}</strong>${icon('ChevronRight')}</div><span class="meta">${rows.filter(c=>c.source===s.id).length} ${t('requestCount')} · ${n(540+i*110)} ms</span><span class="meta">${t('notGraded')}</span></a>`).join('')}</div></section><details class="divider"><summary>${icon('ChevronRight')}${t('storage')}</summary><p class="section-note">${t('storageHint')}</p></details></div>`,btn('checkModel','openCheck'))}${selected?`<aside class="inspector">${heading(selected.name,'/monitor')}<div class="scroll flow"><p class="section-note">${t('recent24')}</p><section><h3>${t('failureEvents')}</h3>${calls.filter(c=>c.source===id&&c.status==='failedCall'&&c.at>Date.now()-86400000).map(c=>`<div class="summary-row divider"><div class="identity"><strong>${e(c.model)}</strong><small>${localDate(c.at)}</small><span class="warning">${t('failedCall')} · 429</span></div>${link(t('audit'),'/audit/'+c.id,'tt-act')}</div>`).join('')||`<p class="empty">${t('noQualityEvents')}</p>`}</section><section class="probe-box"><h3>${t('checkModel')}</h3><p class="section-note">${t('checkCost')}</p>${select('model',state.checkModel||selected.models[0]?.id,selected.models.map(m=>[m.id,m.id]),'checkModel')}${select('checkRule',state.checkRule||'answer',['answer','json','tools'].map(k=>[k,t(k)]),'checkRule')}${btn('runCheck','runCheck','',true)}${state.checked?`<p class="notice" role="status">${t('simulatedCheck')}</p>`:''}</section></div></aside>`:''}</div>`}
function directoryRows(){return state.sources.flatMap(s=>s.directory.map(m=>({...m,source:s.id,saved:s.models.some(row=>row.id===m.id)}))).filter(m=>(!state.directorySource||state.directorySource===m.source)&&(!state.directoryCapability||m.cap.includes(state.directoryCapability))&&(m.id+' '+sourceById(m.source)?.name).toLowerCase().includes((state.queries.gateway||'').toLowerCase()))}
